/* Hardware-measured per-tile plane constants (AGX probe capture
 * residual-children-dense-plan-v1; TASK.md later-132..140).
 * Assignment of Apple facet planes to walle children: side-aware
 * geometric pairing (12 primaries) plus the per-pixel reference
 * oracle for facets spanning multiple walle children.  Keyed on
 * the state's expanded-radius word and the walle fixed-point
 * vertices (verts alone recur across saturated states).
 * 'trusted' bypasses the shader's rasterizer-owner filter for
 * children whose pixels the oracle proved against the reference. */
struct wlg_hw_tile { int16_t tx, ty; uint32_t c[2]; };
/* Hardware-measured internal-precision plane for one tile: the AGX
 * ITER evaluates sub-ulp-accurate planes; value = (a*lx + b*ly + c)
 * * 2^-60, exported RTZ24.  Region 1 (when e3 != 0) applies where
 * lx >= e0 + (e1*ly + e2)/e3 - the hardware sub-primitive split. */
struct wlg_hw_ext {
    int16_t tx, ty;
    uint8_t e0, e1, e2, e3;
    int64_t plane[2][2][3];
};
struct wlg_hw_child {
    uint32_t radius_bits;
    int32_t  fixed[3][2];
    uint32_t slope[2][2];
    uint32_t tile_count;
    const struct wlg_hw_tile* tiles;
    uint8_t  trusted;
    const struct wlg_hw_ext* ext;
};
